#' @title Compute chromosome arm ratios
#'
#' @description
#' Computes chromosome arm log ratio profiles by
#' subtracting a reference chromosome arm expression
#' profile from chromosome arm mean expression values.
#'
#' @param arm_means_matrix Matrix of chromosome arm mean
#' expression values generated by compute_arm_means().
#' @param xenium.obj Normalised Xenium object.
#' @param group_var Optional metadata variable used to define
#' reference cells. If NULL, all cells are used.
#' @param reference Optional groups within group_var used to
#' construct the reference chromosome arm profile. If NULL,
#' all cells (or all groups within group_var) are used.
#'
#' @returns A matrix of chromosome arm log ratio values
#' with chromosome arms as rows and cells as columns.
#'
#' @examples
#' \dontrun{
#' # Compute chromosome arm ratios using specific reference(s)
#' arm_ratios <- compute_arm_ratios(arm_means_matrix,
#'                                 xenium.obj,
#'                                 group_var = "group",
#'                                 reference = c("Fallopian Tube Epithelium",
#'                                 "Secretory Epithelial Cells"))
#'
#' # Compute chromosome arm ratios using global mean
#' arm_ratios <- compute_arm_ratios(arm_means_matrix,
#'                                 xenium.obj)}
#'
#' @export
compute_arm_ratios <- function(
    arm_means_matrix,
    xenium.obj,
    group_var = NULL,
    reference = NULL
) {

  reference_arm_means <- compute_reference(
    xenium.obj = xenium.obj,
    group_var = group_var,
    group_names = reference
  )

  ref_vec <- reference_arm_means$mean_arm_expr

  arm_ratios <- arm_means_matrix - ref_vec

  return(arm_ratios)
}
